sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float origin;
uniform float amount;
uniform float start;
uniform float before;
uniform float tuneHead;
uniform float tuneTail;
bool arc(float2 d, float k, float len, float w, out float2 hit) {
    if (abs(k) * len < 0.0001) {
        hit = d;
    } else {
        float r = 1.0 / k;
        float2 c = float2(d.x, d.y - r);
        float sg = sign(k);
        hit = float2(atan(c.x, -sg * c.y) / abs(k), r - sg * length(c));
    }
    return hit.x >= 0.0 && hit.x <= len && abs(hit.y) <= w;
}
half4 at(float2 p) {
    float3 g = fromLayer * float3(p, 1.0);
    return image.eval(g.xy / g.z);
}
half4 main(float2 coord) {
    float theta = -radians(clamp(amount, -180.0, 180.0));
    if (abs(theta) < 0.0001) return image.eval(coord);
    float3 h = toLayer * float3(coord, 1.0);
    float2 lp = h.xy / h.z;
    float2 o = float2(layer.x * 0.5, layer.y);
    float2 u = float2(0.0, -1.0);
    float2 v = float2(1.0, 0.0);
    float len = layer.y;
    float wide = layer.x;
    if (origin < 0.5) {
        o = float2(0.0, layer.y * 0.5); u = float2(1.0, 0.0); v = float2(0.0, 1.0); len = layer.x; wide = layer.y;
    } else if (origin < 1.5) {
        o = float2(layer.x, layer.y * 0.5); u = float2(-1.0, 0.0); v = float2(0.0, -1.0); len = layer.x; wide = layer.y;
    } else if (origin < 2.5) {
        o = float2(layer.x * 0.5, 0.0); u = float2(0.0, 1.0); v = float2(-1.0, 0.0);
    }
    float2 q = float2(dot(lp - o, u), dot(lp - o, v));
    float s = clamp(start, 0.0, 1.0) * len;
    float w = wide * 0.5 + 1.0;
    float bendmost = 2.0 / max(min(layer.x, layer.y), 0.0001);
    float2 hit;
    if (len > s && arc(float2(q.x - s, q.y), clamp(theta / (len - s), -bendmost, bendmost), len - s + 1.0, w, hit)) return at(o + (s + hit.x) * u + hit.y * v);
    float side = before < 0.5 ? 0.0 : before < 1.5 ? -1.0 : 1.0;
    if (side == 0.0) {
        if (q.x >= -1.0 && q.x <= s && abs(q.y) <= w) return at(o + q.x * u + q.y * v);
    } else if (s > 0.0 && arc(float2(s - q.x, -q.y), clamp(side * theta / s, -bendmost, bendmost), s + 1.0, w, hit)) {
        return at(o + (s - hit.x) * u - hit.y * v);
    }
    return half4(0.0);
}
